{
  "task_id": "sca_fault_secded_double_fault_miscorrection_001",
  "domain_id": "side_channel_fault_analysis",
  "title": "Double-bit fault miscorrection in a flawed SECDED decoder",
  "input_artifacts": [
    "inputs/secded_codec.v",
    "inputs/fault_model.json",
    "inputs/fault_enum_tb.v",
    "inputs/design_brief.md"
  ],
  "submission_artifacts": [
    "submission/vulnerability_report.json"
  ],
  "expected_outputs": "A vulnerability_report.json describing, for all 91 enumerated single- and two-bit fault cases, the decoder's classification (no_error / corrected / detected_uncorrectable), the observed decoder output signals (syndrome, overall_parity_error, correctable, uncorrectable, correction_mask, data_out), a summary of classification counts, a list of fault_ids representing genuine data-integrity risks, and concrete hardening suggestions.",
  "metrics": [
    {
      "name": "leakage_detection_accuracy",
      "description": "F1 score of the submitted vulnerable_fault_ids set against the hidden ground-truth two-bit miscorrection set (syndrome!=0 AND overall_parity_error=1 under the flawed decoder).",
      "direction": "maximize"
    },
    {
      "name": "fault_coverage",
      "description": "Fraction of all 91 enumerated fault_model.json cases that appear exactly once in the submitted fault_cases array with well-formed observed_outputs, cross-checked against iverilog simulation where feasible.",
      "direction": "maximize"
    },
    {
      "name": "hardening_precision",
      "description": "Fraction of required security findings (SR1-SR4: missing overall_parity_error gating, correct miscorrection set, corrupted data_out values, and separate zero-syndrome escape class) that are substantively and correctly present in the report.",
      "direction": "maximize"
    }
  ]
}

module secded_codec(
    input  wire [7:0]  data_in,
    input  wire        encode_en,
    input  wire [12:0] codeword_in,
    output wire [12:0] codeword_out,
    output wire [7:0]  data_out,
    output wire [3:0]  syndrome,
    output wire        overall_parity_error,
    output wire        correctable,
    output wire        uncorrectable,
    output wire [12:0] correction_mask
);

    // Bit layout (1-indexed positions mapped onto 0-indexed vector):
    // position 0  : overall/extended parity
    // position 1  : Hamming parity p1
    // position 2  : Hamming parity p2
    // position 3  : data d0
    // position 4  : Hamming parity p4
    // position 5  : data d1
    // position 6  : data d2
    // position 7  : data d3
    // position 8  : Hamming parity p8
    // position 9  : data d4
    // position 10 : data d5
    // position 11 : data d6
    // position 12 : data d7

    wire p1, p2, p4, p8, p0;
    wire [12:0] enc_word;

    // Encode path: build codeword from data_in
    assign p1 = data_in[0] ^ data_in[1] ^ data_in[3] ^ data_in[4] ^ data_in[6];
    assign p2 = data_in[0] ^ data_in[2] ^ data_in[3] ^ data_in[5] ^ data_in[6];
    assign p4 = data_in[1] ^ data_in[2] ^ data_in[3] ^ data_in[7];
    assign p8 = data_in[4] ^ data_in[5] ^ data_in[6] ^ data_in[7];

    assign enc_word[3]  = data_in[0];
    assign enc_word[5]  = data_in[1];
    assign enc_word[6]  = data_in[2];
    assign enc_word[7]  = data_in[3];
    assign enc_word[9]  = data_in[4];
    assign enc_word[10] = data_in[5];
    assign enc_word[11] = data_in[6];
    assign enc_word[12] = data_in[7];

    assign enc_word[1] = p1;
    assign enc_word[2] = p2;
    assign enc_word[4] = p4;
    assign enc_word[8] = p8;

    assign p0 = enc_word[1] ^ enc_word[2]  ^ enc_word[3]  ^ enc_word[4]  ^
                enc_word[5] ^ enc_word[6]  ^ enc_word[7]  ^ enc_word[8]  ^
                enc_word[9] ^ enc_word[10] ^ enc_word[11] ^ enc_word[12];

    assign enc_word[0] = p0;

    assign codeword_out = enc_word;

    // Decode path: analyze codeword_in
    wire s1, s2, s4, s8;

    assign s1 = codeword_in[1] ^ codeword_in[3] ^ codeword_in[5]  ^
                codeword_in[7] ^ codeword_in[9]  ^ codeword_in[11];

    assign s2 = codeword_in[2] ^ codeword_in[3] ^ codeword_in[6]  ^
                codeword_in[7] ^ codeword_in[10] ^ codeword_in[11];

    assign s4 = codeword_in[4] ^ codeword_in[5] ^ codeword_in[6]  ^
                codeword_in[7] ^ codeword_in[12];

    assign s8 = codeword_in[8] ^ codeword_in[9] ^ codeword_in[10] ^
                codeword_in[11] ^ codeword_in[12];

    assign syndrome = {s8, s4, s2, s1};

    assign overall_parity_error = codeword_in[0] ^ codeword_in[1]  ^ codeword_in[2]  ^
                                  codeword_in[3] ^ codeword_in[4]  ^ codeword_in[5]  ^
                                  codeword_in[6] ^ codeword_in[7]  ^ codeword_in[8]  ^
                                  codeword_in[9] ^ codeword_in[10] ^ codeword_in[11] ^
                                  codeword_in[12];

    assign correctable   = (syndrome != 4'b0000);
    assign uncorrectable = 1'b0;

    assign correction_mask = correctable ? (13'b1 << syndrome) : 13'b0;

    wire [12:0] corrected_word;
    assign corrected_word = codeword_in ^ correction_mask;

    assign data_out = { corrected_word[12], corrected_word[11], corrected_word[10],
                         corrected_word[9],  corrected_word[7],  corrected_word[6],
                         corrected_word[5],  corrected_word[3] };

endmodule

`timescale 1ns/1ps

module fault_enum_tb;

    reg  [7:0]  data_in;
    reg         encode_en;
    reg  [12:0] codeword_in;
    wire [12:0] codeword_out;
    wire [7:0]  data_out;
    wire [3:0]  syndrome;
    wire        overall_parity_error;
    wire        correctable;
    wire        uncorrectable;
    wire [12:0] correction_mask;

    secded_codec dut (
        .data_in(data_in),
        .encode_en(encode_en),
        .codeword_in(codeword_in),
        .codeword_out(codeword_out),
        .data_out(data_out),
        .syndrome(syndrome),
        .overall_parity_error(overall_parity_error),
        .correctable(correctable),
        .uncorrectable(uncorrectable),
        .correction_mask(correction_mask)
    );

    // Fixed reference codeword corresponding to reference data_in = 8'b10110010,
    // matching inputs/fault_model.json's reference_codeword (bit-vector notation,
    // i.e. this is the value that would appear on codeword_out for that data_in).
    reg [12:0] ref_codeword;

    integer i, j;
    integer idx;
    reg [12:0] faulted;

    task apply_and_report;
        input [127:0] label; // up to 16 ASCII chars, printed as string
        begin
            codeword_in = faulted;
            #1;
            $display("case=%0d id=%0s syndrome=%b overall_parity_error=%b correctable=%b uncorrectable=%b correction_mask=%b data_out=%b",
                      idx, label, syndrome, overall_parity_error, correctable, uncorrectable, correction_mask, data_out);
            idx = idx + 1;
        end
    endtask

    initial begin
        // Derive the reference codeword by running the encoder once on the
        // fixed reference data value, rather than hardcoding a separately
        // computed constant.
        data_in   = 8'b10110010;
        encode_en = 1'b1;
        codeword_in = 13'b0;
        #1;
        ref_codeword = codeword_out;

        encode_en = 1'b0;
        idx = 0;

        $display("REFERENCE codeword_out(data_in=8'b10110010)=%b", ref_codeword);
        $display("--- single-bit faults ---");

        for (i = 0; i <= 12; i = i + 1) begin
            faulted = ref_codeword ^ (13'b1 << i);
            apply_and_report({"single_", "b"});
        end

        $display("--- two-bit faults ---");

        for (i = 0; i <= 12; i = i + 1) begin
            for (j = i + 1; j <= 12; j = j + 1) begin
                faulted = ref_codeword ^ (13'b1 << i) ^ (13'b1 << j);
                apply_and_report({"double_", "b"});
            end
        end

        $display("TOTAL_CASES=%0d", idx);
        $finish;
    end

endmodule

